contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address newOwner) public payable {
        // no precondition on newOwner
        // Read owner before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // Attempt the call and record whether it reverted and the returned boolean
        bool reverted;
        bool returnedFalse = false;
        bool returnedTrue = false;
        bool success = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            if (success) returnedTrue = true; else returnedFalse = true;
        }

        // Read owner after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General invariant: either the call reverted and owner unchanged, or the call succeeded and returned true and owner equals newOwner.
        assert((reverted && ownerAfter == ownerBefore) || (!reverted && returnedTrue && ownerAfter == newOwner));
    }

    receive() external payable {}
}

